module.exports = function (RED) {
    "use strict";

    function PublishNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.rulename = config.rulename;
        node.fusionTarget = config.fusionTarget;
        node.branchId = config.branchId;   // 来自配置（上面 HTML 保存的）

        this.on("input", function (msg, send, done) {
            // 规则名 & 目标表从配置里带进去
            msg.rulename = node.rulename;
            msg.fusionTarget = node.fusionTarget;

            // 1）优先保留 msg 里已有的 branchId（如果前面节点已经写过）
            // 2）否则用本节点配置里的 branchId
            let branchId = (msg.branchId != null && msg.branchId !== "")
                ? msg.branchId
                : node.branchId;

            // 统一转成 number 或 null，方便后端 asInt()
            if (branchId !== undefined && branchId !== null && branchId !== "") {
                const n = Number(branchId);
                branchId = Number.isNaN(n) ? null : n;
            } else {
                branchId = null;
            }

            msg.branchId = branchId;

            // 删除 _msgid，避免噪音
            delete msg._msgid;

            // 收集当前 flow 的所有节点
            const flowNodes = [];
            RED.nodes.eachNode(function (n) {
                flowNodes.push(n);
            });

            const flowJson = JSON.stringify(flowNodes, null, 2);

            // 发给后端的数据
            const dataToSend = {
                branchId: branchId,          // number 或 null
                ruleJson: msg,               // DSL + 其他信息
                flowJson: flowJson,          // Node-RED 流程
                fusionTarget: node.fusionTarget
            };

            const postData = JSON.stringify(dataToSend);
            console.log("[Publish] sending payload:", postData);

            const http = require("http");
            const options = {
                hostname: "127.0.0.1",
                port: 8080,
                path: "/api/node-red/uploadrule",
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Content-Length": Buffer.byteLength(postData)
                }
            };

            const req = http.request(options, (res) => {
                res.setEncoding("utf8");
                res.on("data", (chunk) => {
                    console.log("[Publish] Response:", chunk);
                });
                res.on("end", () => {
                    if (done) done();
                });
            });

            req.on("error", (e) => {
                console.error("[Publish] Problem with request:", e.message);
                if (done) done(e);
            });

            req.write(postData);
            req.end();
        });
    }

    RED.nodes.registerType("Publish", PublishNode);
};